changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.plain_search_384( p_query vector(384), p_collections text[], p_where jsonb, p_where_path text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 <=> p_query)::float8, c.metadata FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m2 JOIN nexus.catalog_documents d2 ON d2.tenant_id = m2.tenant_id AND d2.tumbler = m2.doc_id WHERE m2.tenant_id = m.tenant_id AND m2.chash = m.chash AND d2.deleted_at IS NULL))) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_384 <=> p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.plain_search_768( p_query vector(768), p_collections text[], p_where jsonb, p_where_path text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 <=> p_query)::float8, c.metadata FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m2 JOIN nexus.catalog_documents d2 ON d2.tenant_id = m2.tenant_id AND d2.tumbler = m2.doc_id WHERE m2.tenant_id = m.tenant_id AND m2.chash = m.chash AND d2.deleted_at IS NULL))) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_768 <=> p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.plain_search_1024( p_query vector(1024), p_collections text[], p_where jsonb, p_where_path text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 <=> p_query)::float8, c.metadata FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_1024 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m2 JOIN nexus.catalog_documents d2 ON d2.tenant_id = m2.tenant_id AND d2.tumbler = m2.doc_id WHERE m2.tenant_id = m.tenant_id AND m2.chash = m.chash AND d2.deleted_at IS NULL))) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_1024 <=> p_query, encode(c.chash, 'hex') LIMIT p_n $$;

rollback.sql:
DROP FUNCTION IF EXISTS nexus.plain_search_384(vector, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.plain_search_768(vector, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.plain_search_1024(vector, text[], jsonb, text, int);
